<template>
  <section class="cl-root" aria-label="知识点学习" :aria-busy="!!state.busy">
    <p class="cw-kicker">从理解，到练习</p><h2>{{ label }}</h2>
    <p v-if="state.error" class="cw-status cw-error" role="alert">{{ state.error }}</p>
    <p v-if="state.busy" role="status">{{ state.busy === 'generate' ? '正在生成，最长约 20 秒…' : '正在处理…' }}</p>
    <button :disabled="!!state.busy" @click="controller.loadEvidence()">刷新学习记录</button>
    <template v-if="state.evidence">
      <div class="cl-status"><strong>{{ statuses[state.evidence.status] }}</strong><p>实际作答 {{ state.evidence.counts.attempts }} 次 · 近七天错答 {{ state.evidence.counts.wrong_attempts_7d }} 次 · 到期复习 {{ state.evidence.counts.due_reviews }} 项</p><p class="cw-caption">仅反映近期训练表现，非掌握率。规则 {{ state.evidence.rule_version }}</p></div>
      <p v-if="!state.evidence.active_support" class="cw-status">此概念无有效来源，保留历史；请先补充来源再生成练习或计划。</p>
      <div class="cl-section"><h3>练一道，马上复盘</h3><p v-if="!linked.length">{{ state.evidence.question_refs.total ? '当前题目页没有已关联题目，可在下方查找并翻页练习。' : '还没有明确关联的题目。可以关联已有题目，或从原文创建基础练习。' }}</p><button v-for="item in linked" :key="`${item.artifact_id}-${item.question_index}`" :disabled="!!state.busy" @click="choose(item)">{{ item.question.stem || item.question.question }}</button>
        <article v-if="state.selected" class="cl-question"><p class="cw-kicker">当前问题</p><h3>{{ state.selected.question.stem || state.selected.question.question }}</h3><p v-for="option in state.selected.question.options" :key="option">{{ option }}</p><label>你的回答<textarea :value="state.answer" maxlength="4000" :disabled="!!state.busy || !!state.answerReceipt" @input="controller.setAnswer(($event.target as HTMLTextAreaElement).value)" /></label><button class="cw-primary" :disabled="!!state.busy || !state.answer.trim() || !!state.answerReceipt" @click="controller.submitAnswer()">提交并查看反馈</button><div v-if="state.answerReceipt" class="cl-confirm" role="status"><strong>{{ state.answerReceipt.is_correct ? '本题回答正确' : '本题需要再巩固' }}</strong><p>{{ state.answerReceipt.feedback }}</p><p>参考答案：{{ state.answerReceipt.reference_answer || state.selected.question.answer }}</p><p>{{ state.selected.question.analysis || state.selected.question.explanation }}</p><RouterLink to="/wrongbook">进入错题复习</RouterLink></div></article>
      </div>
      <details class="cl-section"><summary>关联或解除已有题目</summary><form @submit.prevent="controller.loadCandidates(query)"><label>查找课程内的题目<input v-model="query" maxlength="160" /></label><button :disabled="!!state.busy">搜索题目</button></form><article v-for="item in state.candidates.items" :key="`${item.artifact_id}-${item.question_index}`" class="cw-quote"><p>{{ item.question.stem || item.question.question }}</p><button v-if="item.linked" :disabled="!!state.busy" @click="choose(item)">练习本题</button><button :disabled="!!state.busy" @click="controller.previewLinks([identity(item)], !item.linked)">{{ item.linked ? '预览解除关联' : '预览关联' }}</button></article><nav class="cw-pagination" aria-label="题目候选分页"><button :disabled="!!state.busy || state.candidates.offset === 0" @click="controller.loadCandidates(query, Math.max(0, state.candidates.offset-50))">前页</button><span>{{ state.candidates.total }} 道题目</span><button :disabled="!!state.busy || state.candidates.offset+50 >= state.candidates.total" @click="controller.loadCandidates(query, state.candidates.offset+50)">后页</button></nav><div v-if="state.linksPreview" class="cl-confirm"><p>将改变 {{ state.linksPreview.changed_count }} 项关联，原作答与错题保留。</p><button :disabled="!!state.busy" @click="controller.confirmLinks()">确认关联变更</button></div></details>
      <CoursePractice :work="state.work" :preview="state.practicePreview" :receipt="state.practiceReceipt" :busy="!!state.busy" @generate="controller.generatePractice" @decisions="controller.setDecisions" @review="controller.reviewPractice" @confirm="controller.confirmPractice" @cancel="controller.cancel" @recover="controller.recoverWork" />
      <CoursePathPreview :options="state.pathOptions" :preview="state.pathPreview" :receipt="state.planReceipt" :busy="!!state.busy" :goals="goals" @options="controller.setPathOptions" @preview="controller.previewPath" @confirm="controller.confirmPath" />
      <CourseAssistant v-if="assistantEnabled" ref="assistant" :scope="scope" :course-id="courseId" :node-id="nodeId" @citation="$emit('citation', $event)" />
      <details class="cl-section"><summary>作答、复习与计划记录</summary><p v-for="attempt in state.evidence.attempts.items" :key="attempt.attempt_id">{{ new Date(attempt.created_at).toLocaleString() }} · {{ attempt.is_correct ? '答对' : '答错' }}</p><p v-for="wrong in state.evidence.wrongs.items" :key="wrong.wrong_id"><RouterLink to="/wrongbook">{{ wrong.mastered ? '已复习稳定' : wrong.due ? '有一项复习到期' : '等待下次复习' }}</RouterLink></p><p v-for="plan in state.evidence.plans.items" :key="`${plan.plan_id}-${plan.day_index}`"><RouterLink :to="`/study-plan?plan=${plan.plan_id}`">{{ plan.title }} · 第 {{ plan.day_index+1 }} 天</RouterLink> · {{ plan.completed ? '任务已完成（不等于答对）' : '待完成' }}</p><nav class="cw-pagination" aria-label="学习证据分页"><button :disabled="!!state.busy || state.evidence.attempts.offset === 0" @click="controller.loadEvidence(Math.max(0, state.evidence.attempts.offset-50))">前页记录</button><button :disabled="!!state.busy || !hasMore" @click="controller.loadEvidence(state.evidence.attempts.offset+50)">后页记录</button></nav></details>
      <details class="cl-section" @toggle="loadCourses"><summary>联系另一门课程</summary><p>仅建立导航，不累计另一门课的学习记录。</p><p v-for="item in state.related.items" :key="item.link_id"><RouterLink v-if="item.available && item.route" :to="item.route">{{ item.course_name }} · {{ item.label }}</RouterLink><span v-else>{{ item.course_name }} · {{ item.label }}（{{ item.unavailable_reason }}）</span><button :disabled="!!state.busy" @click="controller.previewRelated({ other_course_id: item.course_id, other_concept_id: item.concept_id, relation: 'related', active: false })">预览解除</button></p><label>搜索另一门课程<input v-model="courseQuery" maxlength="160" /><button :disabled="!!state.busy" @click="findCourses">查找课程</button></label><label>目标课程<select v-model="otherCourse" @change="findConcepts"><option value="">请选择</option><option v-for="course in courses" :key="course.course_id" :value="course.course_id">{{ course.name }}</option></select></label><label>搜索知识点<input v-model="conceptQuery" maxlength="160" /><button :disabled="!otherCourse" @click="findConcepts">查找知识点</button></label><label>目标知识点<select v-model="otherNode"><option value="">请选择</option><option v-for="node in concepts" :key="node.id" :value="node.id">{{ node.label }}</option></select></label><button :disabled="!!state.busy || !otherNode || !otherCourse" @click="controller.previewRelated({ other_course_id: otherCourse, other_concept_id: otherNode, relation: 'related', active: true })">预览跨课联系</button><div v-if="state.relatedPreview" class="cl-confirm"><p>仅改变 {{ state.relatedPreview.changed_count }} 条人工联系。</p><button :disabled="!!state.busy" @click="controller.confirmRelated()">确认联系变更</button></div></details>
      <p v-if="state.lastReceipt" role="status">已保存。需要撤销时，可在“整理课程 → 操作与已保存草稿”查看。</p>
    </template>
  </section>
</template>
<script setup lang="ts">
import { computed, onUnmounted, shallowReactive, shallowRef, ref, watch } from 'vue'
import { ElMessageBox } from 'element-plus'
import * as api from '../../services/api'
import { createCourseLearningController } from '../../course-graph/learning-state'
import type { GraphCourse } from '../../types/courseGraph'
import type { QuestionCandidate, QuestionRef } from '../../types/courseLearning'
import CoursePractice from './CoursePractice.vue'
import CoursePathPreview from './CoursePathPreview.vue'
import CourseAssistant from './CourseAssistant.vue'
const assistantEnabled = import.meta.env.VITE_ENABLE_GRAPH_ASSISTANT === 'true'
const assistant = ref<{ dirty(): boolean } | null>(null)
defineEmits<{ citation: [id: string] }>()
const props = defineProps<{ scope: string; courseId: string; nodeId: string; label: string }>()
const controller = createCourseLearningController(api, shallowReactive), state = controller.state
const query = ref(''), courseQuery = ref(''), conceptQuery = ref(''), otherCourse = ref(''), otherNode = ref('')
const courses = shallowRef<GraphCourse[]>([]), concepts = shallowRef<{ id: string; label: string }[]>([]), goals = shallowRef<{ artifact_id: string; title: string }[]>([])
const linked = computed(() => state.candidates.items.filter(q => q.linked)), statuses = { no_evidence: '暂无训练证据', practiced: '已有练习记录', needs_reinforcement: '需要巩固', recently_stable: '近期表现稳定' }
const hasMore = computed(() => state.evidence && [state.evidence.attempts, state.evidence.plans, state.evidence.wrongs, state.evidence.question_refs].some(p => p.offset+p.limit < p.total))
const identity = (q: QuestionRef): QuestionRef => ({ artifact_id: q.artifact_id, question_index: q.question_index, question_digest: q.question_digest })
let generation = 0, leaveApproved = false
watch(() => [state.answer, state.work, state.practicePreview, state.pathPreview, state.linksPreview, state.relatedPreview], () => { leaveApproved = false })
watch(() => [props.scope, props.courseId, props.nodeId], async () => { const e = ++generation; leaveApproved = false; courses.value = []; concepts.value = []; goals.value = []; otherCourse.value = ''; otherNode.value = ''; await controller.open(props.scope, props.courseId, props.nodeId, true); try { const rows = await api.getReverseGoals(); if (e === generation) goals.value = rows.map(r => ({ artifact_id: r.goal_id, title: r.title })) } catch { /* Optional goals leave the explicit goal field usable. */ } }, { immediate: true })
async function canLeave() { if ((!controller.dirty() && !assistant.value?.dirty()) || leaveApproved) return true; try { await ElMessageBox.confirm('有未提交回答、待审核草稿或预览。关闭面板会保留当前内容；切换知识点将放弃未保存输入。', '保留当前学习？', { confirmButtonText: '继续离开', cancelButtonText: '留在这里' }); leaveApproved = true; return true } catch { return false } }
async function choose(item: QuestionCandidate) { if (state.answer.trim() && !state.answerReceipt && !await canLeave()) return; controller.chooseQuestion(item) }
async function findCourses() { const e = generation; try { const page = await api.listGraphCourses(courseQuery.value); if (e === generation) courses.value = page.items.filter(c => c.course_id !== props.courseId) } catch { if (e === generation) state.error = '课程列表读取失败，可重试。' } }
function loadCourses(event: Event) { if ((event.target as HTMLDetailsElement).open && !courses.value.length) void findCourses() }
async function findConcepts() { const e = generation, cid = otherCourse.value; otherNode.value = ''; concepts.value = []; if (!cid) return; try { const page = await api.getCourseConceptPage(cid, { q: conceptQuery.value }); if (e === generation && cid === otherCourse.value) concepts.value = page.items } catch { if (e === generation) state.error = '目标知识点读取失败，可重试。' } }
function invalidate() { ++generation; controller.resetIdentity(); goals.value = []; courses.value = []; concepts.value = [] }
onUnmounted(() => { ++generation; controller.dispose() })
defineExpose({ canLeave, invalidate })
</script>
